parameters.jsCode:
const input = $json.output || $json.text || $json.content;

let data;

try {
  data = typeof input === "string"
    ? JSON.parse(input)
    : input;
} catch (error) {
  return [{
    json: {
      success: false,
      error: "Invalid JSON from Comparison AI Agent",
      raw_output: input
    }
  }];
}

return [{
  json: {
    success: true,

    competitor_1: data.competitor_1 || "Not Available",
    competitor_2: data.competitor_2 || "Not Available",

    strengths: data.comparison?.strengths || "Not Available",
    weaknesses: data.comparison?.weaknesses || "Not Available",
    opportunities: data.comparison?.opportunities || "Not Available",
    threats: data.comparison?.threats || "Not Available",

    customer_satisfaction:
      data.comparison?.customer_satisfaction || "Not Available",

    sentiment:
      data.comparison?.sentiment || "Not Available",

    overall_position:
      data.comparison?.overall_position || "Not Available",

    winner: data.winner || "Not Available",

    winner_reason:
      data.winner_reason || "Not Available",

    key_differences:
      (data.key_differences || []).join("\n• "),

    business_insights:
      (data.business_insights || []).join("\n• "),

    recommendation:
      data.recommendation || "Not Available",

    // Complete comparison story
    comparison_story: `
COMPETITOR COMPARISON REPORT

${data.competitor_1 || "Competitor 1"} vs ${data.competitor_2 || "Competitor 2"}

STRENGTHS
${data.comparison?.strengths || "Not Available"}

WEAKNESSES
${data.comparison?.weaknesses || "Not Available"}

OPPORTUNITIES
${data.comparison?.opportunities || "Not Available"}

THREATS
${data.comparison?.threats || "Not Available"}

CUSTOMER SATISFACTION
${data.comparison?.customer_satisfaction || "Not Available"}

SENTIMENT
${data.comparison?.sentiment || "Not Available"}

OVERALL POSITION
${data.comparison?.overall_position || "Not Available"}

WINNER
${data.winner || "Not Available"}

WHY?
${data.winner_reason || "Not Available"}

KEY DIFFERENCES
• ${(data.key_differences || []).join("\n• ")}

BUSINESS INSIGHTS
• ${(data.business_insights || []).join("\n• ")}

RECOMMENDATION
${data.recommendation || "Not Available"}
`
  }
}];
